<script setup lang="ts">
import {ref,onMounted,computed,toRaw} from 'vue';import {api} from '../lib/api';import {initialPlans,money,type Plan,type PlatformConfig} from '../lib/commercial';import Icon from './Icon.vue';import Modal from './ui/Modal.vue';import Toggle from './ui/Toggle.vue';
const data=ref<any>();const error=ref('');const notice=ref('');const tab=ref('overview');const busy=ref(false);const plan=ref<Plan>();const editPlan=ref(false);const config=ref<PlatformConfig>();
const latestPlans=computed(()=>{const map=new Map<string,Plan>();for(const p of data.value?.plans||[])if(!map.has(p.key)||map.get(p.key)!.version<p.version)map.set(p.key,p);return [...map.values()];});
const paidTotals=computed(()=>['USD','INR'].map(currency=>({currency,amount:(data.value?.invoices||[]).filter((i:any)=>i.currency===currency&&i.state==='paid').reduce((n:number,i:any)=>n+i.amount,0)})));
async function load(){try{data.value=await api('/master');config.value=structuredClone(toRaw(data.value.config));error.value='';}catch(e:any){error.value=e.message;}}
async function saveConfig(){busy.value=true;try{await api('/master/config',{method:'PATCH',body:config.value,version:data.value.version});await load();notice.value='Platform configuration saved';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
function newPlan(p?:Plan){plan.value=p?structuredClone(toRaw(p)):{...initialPlans()[1],key:'custom',name:'Custom',id:'new',version:1,published:false};editPlan.value=true;}
async function savePlan(){busy.value=true;try{await api('/master/plans',{method:'POST',body:plan.value});editPlan.value=false;await load();notice.value='New immutable plan version saved. Existing subscriptions keep their previous version.';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
function addModel(){config.value!.models.push({id:'model-'+crypto.randomUUID().slice(0,8),name:'New model',provider:'openai',model:'',currency:'USD',inputMicrosPerMillion:0,outputMicrosPerMillion:0,cachedInputMicrosPerMillion:0,actionMicros:0,maxOutputTokens:1024,enabled:false,credentialRef:'PROVIDER_API_KEY'});}
function addPromo(){config.value!.promos.push({code:'WELCOME'+(config.value!.promos.length+1),percentOff:10,expiresAt:new Date(Date.now()+30*86400000).toISOString(),maxRedemptions:100,planKeys:[],active:true});}
async function suspend(tenant:any){const s=data.value.subscriptions.find((s:any)=>s.workspace_id===tenant.id);try{await api('/master/suspension',{method:'POST',body:{workspaceId:tenant.id,suspended:s?.state!=='suspended',reason:'Platform owner changed workspace availability'}});await load();notice.value='Workspace availability updated';}catch(e:any){error.value=e.message;}}
onMounted(load);
</script>
<template><div class="page-heading"><div><div class="greeting">PLATFORM OWNER · RESTRICTED ACCESS</div><h1>A business behind every workspace.</h1><p>Manage the catalog, payment policies, model economics, and platform access.</p></div><span class="pill sample"><Icon name="lock" :size="14"/>Master console</span></div><p v-if="error" class="form-error mb-5" role="alert">{{error}}</p><p v-if="notice" class="success-banner" role="status">{{notice}}</p><template v-if="data&&config"><div class="master-tabs tabs"><button v-for="t in ['overview','plans','models','promotions','gateways']" :key="t" :class="{active:tab===t}" @click="tab=t">{{t==='models'?'AI model catalog':t}}</button></div><template v-if="tab==='overview'"><div class="stat-grid"><article class="stat-card stat-featured"><div class="stat-label">Business workspaces<Icon name="building"/></div><div class="stat-number">{{data.tenants.length}}</div><div class="stat-bottom">{{data.tenants.filter((t:any)=>!t.sample).length}} empty / live · {{data.tenants.filter((t:any)=>t.sample).length}} sample</div></article><article class="stat-card"><div class="stat-label">Active subscriptions<Icon name="card"/></div><div class="stat-number">{{data.subscriptions.filter((s:any)=>s.state==='active').length}}</div><div class="stat-bottom">Free and paid entitlements</div></article><article v-for="total in paidTotals" :key="total.currency" class="stat-card"><div class="stat-label">Collected · {{total.currency}}<Icon name="checks"/></div><div class="stat-number revenue-number">{{money(total.amount,total.currency)}}</div><div class="stat-bottom">Verified paid invoices only</div></article></div><section class="panel"><div class="panel-heading mb-5"><div><h2>Workspace portfolio</h2><p>Operational totals without opening customer conversations.</p></div></div><div class="table-scroll"><table><thead><tr><th>Workspace</th><th>Members</th><th>Conversations</th><th>Plan</th><th>Status</th><th>Access control</th></tr></thead><tbody><tr v-for="tenant in data.tenants" :key="tenant.id"><td><strong>{{tenant.name}}</strong><small class="block muted">{{tenant.sample?'Fictional sandbox':'Business workspace'}}</small></td><td>{{tenant.seats}}</td><td>{{tenant.conversations}}</td><td>{{data.subscriptions.find((s:any)=>s.workspace_id===tenant.id)?.plan_id||'Free'}}</td><td><span :class="['status',data.subscriptions.find((s:any)=>s.workspace_id===tenant.id)?.state==='suspended'?'pending':'open']">{{data.subscriptions.find((s:any)=>s.workspace_id===tenant.id)?.state||'active'}}</span></td><td><button class="text-action" @click="suspend(tenant)">{{data.subscriptions.find((s:any)=>s.workspace_id===tenant.id)?.state==='suspended'?'Restore access':'Suspend writes'}}</button></td></tr></tbody></table></div></section><div class="panel policy-note"><Icon name="shield"/><p>Platform access is a separate allowlist. A workspace owner cannot become a platform administrator. Suspended workspaces retain read and billing access so customers can retrieve data and renew.</p></div></template>
<template v-else-if="tab==='plans'"><div class="collection-toolbar no-border"><div><h2>Plans & packages</h2><p class="muted text-xs mt-2">Edits create a new version. Published prices are shown on the pricing page.</p></div><button class="button primary" @click="newPlan()"><Icon name="plus" :size="16"/>Create a plan</button></div><div class="plan-grid"><article v-for="p in latestPlans" :key="p.id" class="panel plan-card"><div class="flex items-center justify-between"><h2>{{p.name}}</h2><span :class="['status',p.published?'open':'pending']">{{p.published?'Published':'Draft'}}</span></div><p>{{p.description}}</p><div class="plan-price">{{money(p.priceMinor,p.currency)}}<span>/ {{p.intervalDays}} days</span></div><ul><li><Icon name="check" :size="14"/>{{p.limits.seats}} team members</li><li><Icon name="check" :size="14"/>{{p.limits.conversations.toLocaleString()}} retained conversations</li><li><Icon name="check" :size="14"/>{{p.limits.sources}} knowledge sources</li><li><Icon :name="p.features.byok?'check':'x'" :size="14"/>Bring your own AI key</li><li><Icon :name="p.features.memory?'check':'x'" :size="14"/>Customer memory</li><li><Icon :name="p.features.databaseRead?'check':'x'" :size="14"/>Database harness</li></ul><button class="button secondary" @click="newPlan(p)"><Icon name="edit" :size="14"/>Edit as new version</button><small>Version {{p.version}} · {{p.currency}} minor-unit pricing</small></article></div></template>
<template v-else-if="tab==='models'"><div class="collection-toolbar no-border"><div><h2>Model economics</h2><p class="muted text-xs mt-2">Configure your selling rates independently of provider costs.</p></div><button class="button primary" @click="addModel"><Icon name="plus" :size="16"/>Add model</button></div><div class="info-box mb-5"><Icon name="shield"/>Model execution is disabled in this release. Prices and credential references can be prepared; no token usage or billing is simulated as real.</div><article v-for="offer in config.models" :key="offer.id" class="panel config-card"><div class="form-grid"><label>Display name<input v-model="offer.name"/></label><label>Provider<select v-model="offer.provider"><option>openai</option><option>anthropic</option><option>gemini</option><option>openrouter</option><option>custom</option></select></label><label>Provider model ID<input v-model="offer.model" placeholder="Exact model identifier"/></label><label>Server credential reference<input v-model="offer.credentialRef" placeholder="PROVIDER_API_KEY"/></label><label>Currency<select v-model="offer.currency"><option>USD</option><option>INR</option></select></label><label>Max output tokens<input type="number" v-model.number="offer.maxOutputTokens" min="1" max="32768"/></label><label>Input price / 1M tokens (micros)<input type="number" v-model.number="offer.inputMicrosPerMillion" min="0"/></label><label>Output price / 1M tokens (micros)<input type="number" v-model.number="offer.outputMicrosPerMillion" min="0"/></label><label>Cached input / 1M tokens (micros)<input type="number" v-model.number="offer.cachedInputMicrosPerMillion" min="0"/></label><label>Price per action (micros)<input type="number" v-model.number="offer.actionMicros" min="0"/></label></div><p class="tiny-note mt-4">1,000,000 micros = 1 {{offer.currency}}. Uncached input, cached input, output, and actions are separate dimensions. Only provider-reported usage can settle a reservation.</p></article><div v-if="!config.models.length" class="empty-state panel"><Icon name="sparkles" :size="35"/><h2>Your model catalog starts here.</h2><p>Add the models you will offer. Keep provider credentials in server-side secret storage.</p></div><button class="button primary mt-5" :disabled="busy" @click="saveConfig">Save model catalog</button></template>
<template v-else-if="tab==='promotions'"><div class="collection-toolbar no-border"><div><h2>Promotions with boundaries</h2><p class="muted text-xs mt-2">Percentage discounts on new plan invoices. No retroactive repricing.</p></div><button class="button primary" @click="addPromo"><Icon name="plus" :size="16"/>Create promotion</button></div><article v-for="(promo,index) in config.promos" :key="index" class="panel config-card"><div class="form-grid"><label>Code<input v-model="promo.code" @input="promo.code=promo.code.toUpperCase()" maxlength="30"/></label><label>Discount (%)<input type="number" v-model.number="promo.percentOff" min="1" max="99"/></label><label>Maximum reservations<input type="number" v-model.number="promo.maxRedemptions" min="1"/></label><label>Expires (UTC)<input type="datetime-local" :value="promo.expiresAt.slice(0,16)" @change="promo.expiresAt=new Date(($event.target as HTMLInputElement).value+'Z').toISOString()"/></label></div><div class="setting-row"><div><strong>Available for new invoices</strong><p>Paid and open invoices count toward the promotion limit.</p></div><Toggle v-model="promo.active" label="Promotion active"/></div></article><div v-if="!config.promos.length" class="empty-state panel"><Icon name="card" :size="35"/><h2>A thoughtful welcome offer.</h2><p>Create a bounded discount for your next customers.</p></div><button class="button primary mt-5" :disabled="busy" @click="saveConfig">Save promotions</button></template>
<template v-else><div class="settings-layout"><section class="panel settings-form"><h2>Payment collection</h2><p class="muted">Gateway credentials are server secrets. Turning on a preference does not bypass setup or verification.</p><div v-for="g in (['stripe','paypal','razorpay'] as const)" :key="g" class="setting-row"><div><strong class="capitalize">{{g}}</strong><p>{{data.gateways[g]?'Credentials present; validate a sandbox payment before launch.':'Not connected. Checkout remains unavailable.'}}</p></div><Toggle v-model="config.gateways[g]" :label="'Offer '+g"/></div><label>Merchant display name<input v-model="config.billingLabel"/></label><label>Billing support email<input type="email" v-model="config.supportEmail" placeholder="billing@yourdomain.com"/></label><label>Grace period before suspension (days)<input type="number" v-model.number="config.graceDays" min="0" max="30"/></label><button class="button primary" :disabled="busy" @click="saveConfig">Save billing policy</button></section><aside class="panel policy-guide"><Icon name="shield" :size="26"/><h2>Payment is a verified event.</h2><p>Checkout redirects do not add credit. A matched successful capture or signed webhook pays the invoice exactly once.</p><h3>Prepaid billing in this release</h3><p>Plan invoices activate a new paid period after payment. Free downgrades apply at the end of the current period. Renewal requires a new paid invoice; automatic recurring mandates are not enabled.</p><h3>Gateway-specific upgrades</h3><p>Razorpay payment-method restrictions and PayPal buyer re-consent require distinct recurring flows. Those are not silently substituted with an unsupported update.</p><h3>Launch configuration</h3><p>The private Sites preview cannot receive public payment webhooks. Use the independent hosting configuration and complete merchant setup before accepting payments.</p></aside></div></template></template>
<Modal :open="editPlan" @update:open="editPlan=$event" title="Shape a plan" description="Save a new immutable version. Existing customers retain their current contract."><form v-if="plan" class="modal-form" @submit.prevent="savePlan"><div class="form-row"><label>Plan key<input v-model="plan.key" required pattern="[a-z][a-z0-9-]{1,30}"/></label><label>Display name<input v-model="plan.name" required/></label></div><label>Description<input v-model="plan.description" maxlength="300"/></label><div class="form-row"><label>Price in minor units<input type="number" min="0" v-model.number="plan.priceMinor" required/></label><label>Currency<select v-model="plan.currency"><option>USD</option><option>INR</option></select></label><label>Period (days)<input type="number" min="1" max="366" v-model.number="plan.intervalDays"/></label></div><div class="form-grid"><label v-for="(_,key) in plan.limits" :key="key">{{String(key).replace(/([A-Z])/g,' $1')}}<input type="number" min="0" v-model.number="plan.limits[key]"/></label></div><div v-for="(_,key) in plan.features" :key="key" class="setting-row compact-row"><span class="capitalize text-xs">{{String(key).replace(/([A-Z])/g,' $1')}}</span><Toggle v-model="plan.features[key]" :label="String(key)"/></div><label>Included prepaid credit (micros)<input type="number" min="0" v-model.number="plan.includedCreditMicros"/></label><div class="setting-row"><div><strong>Publish this version</strong><p>Allow customers to select it and display it on the pricing page.</p></div><Toggle v-model="plan.published" label="Publish plan"/></div><p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button type="button" class="button secondary" @click="editPlan=false">Cancel</button><button class="button primary" :disabled="busy">Save new version</button></div></form></Modal>
</template>
